from h34 import *
M=mcq;F=tf;S=short;N=num
chapter(3,'english','chandrayaan','Chandrayaan',
 ('Rani asks about the Moon','Rani is a curious girl who asks many questions. One morning her brother Pratik shouts that India is on the Moon. The children visit Nandini Aunty, a scientist, who explains how a rocket carried Chandrayaan to the Moon. In this chapter you will read the story, learn the words curious and scientist, use a and an correctly, form words with sk, sw, sp and st, and learn the days of the week with their positions.'),
 [('Curious Rani',['Rani lived in a village and was very curious. She asked many questions to her family, teachers and friends.','She asked why the sky is blue and where the Sun goes at night.','One evening she heard her mother singing about Chanda Mama and asked how far the Moon is.','Her mother said it is very far in the sky, and Rani fell asleep thinking about the Moon.']),
  ('India on the Moon',['Next morning her brother Pratik shouted in excitement, pointing at the TV, Look Rani, India is on the Moon.','On the TV Rani saw photos of machines on the Moon and heard people talking about the landing.','She was confused and asked how Chandrayaan reached the Moon.','Pratik said his friend Vivaan\'s mother, Nandini Aunty, is a scientist, so they went to visit her.']),
  ('Talking to the scientist',['Rani and Pratik saw many models and photographs of rockets in Vivaan\'s house.','Nandini Aunty offered sharbat and asked what Rani wanted to know.','Pratik correctly said that a rocket is used to go to the Moon.','Chandra means Moon and yaan means vehicle, so Chandrayaan means the Moon vehicle.','India launched Chandrayaan on 14 July 2023 and it landed on the Moon on 23 August 2023.','Rani asked if she could go to the Moon too, and Nandini smiled and said maybe, one day.','Rani is curious because she asks many questions, and curiosity is how scientists begin.']),
  ('New words',['Curious means eager to learn and know things. Excitement is the feeling of being very happy and thrilled.','Machines are things that do work. Confused means not sure what is happening.','A scientist is a person who studies and finds out how things work. A rocket is a vehicle that travels very fast into space.']),
  ('A and an',['We use a before a singular word that starts with a consonant sound, like a dog, a cow, a sparrow and a girl.','We use an before a singular word that starts with a vowel sound, like an eagle, an umbrella, an ice-cream man and an egg.','Listen to the sound, not just the letter: an hour starts with a vowel sound, but a university starts with a y sound.','Mary ate an apricot, a chikoo and an orange.']),
  ('Sounds sk, sw, sp and st',['Many words start with two letters that make one sound.','Sw gives swing and sweet. Sk gives skirt and skate. Sp gives spoon and spin. St gives stone and story.','So we say swings in the park, stones in the river, a spoon and a bowl for soup, the story of the boy who cried wolf, and a blue skirt.']),
  ('Days of the week',['There are seven days in a week, and each day has a place in order.','Sunday is the first, Monday the second, Tuesday the third and Wednesday the fourth.','Thursday is the fifth, Friday the sixth and Saturday the seventh.','These position words, first, second, third and so on, are called ordinal numbers.']),
  ('Speak, write and explore',['You can imagine staying on the Moon for ten days and list what you would take, like food, water, a warm suit, a torch and a book.','You can draw the Moon and write a few lines about it with your teacher.','Collect newspaper clippings about Chandrayaan 3 and make a class chart, and ask your family for a song or story about the Moon in your own language.'])],
 [('Fill in a or an: ___ eagle sat on ___ building.',[('Eagle starts with a vowel sound, so we use an.','An goes before vowel sounds.'),('Building starts with a consonant sound, so we use a.','A goes before consonant sounds.'),('So: An eagle sat on a building.','Say it aloud to hear the difference.')]),
  ('Which day is the fifth day of the week?',[('Count from Sunday as first.','Sunday 1, Monday 2, Tuesday 3, Wednesday 4.'),('The next is Thursday.','Thursday is fifth.')]),
  ('What does Chandrayaan mean?',[('Chandra means Moon.','Chandra is the Moon.'),('Yaan means vehicle.','Yaan is a vehicle.'),('So Chandrayaan means the Moon vehicle.','A vehicle made to go to the Moon.')])],
 ('Tell the story of Rani and Chandrayaan, and explain what Chandrayaan means.',['Rani was curious','India landed on the Moon','Nandini Aunty explained about rockets','Chandra means Moon and yaan means vehicle'],['Chandrayaan is a bird','Rani went to the Moon']),
 ['Rani is curious and asks many questions.','Chandrayaan means the Moon vehicle.','Chandrayaan landed on the Moon on 23 August 2023.','Use a before consonant sounds and an before vowel sounds.','The days of the week have positions, first to seventh.'],
 [M('1',1,'How do we know Rani was curious?','She asked many questions',[('She was afraid','Curious means eager to learn'),('She was sleepy','Not the reason')],'She asked why and how all the time.'),
  M('2',1,'What did Pratik shout in excitement?','India is on the Moon',[('It is raining','He was pointing at the TV'),('The Moon is falling','Not in the story')],'He saw the landing on TV.'),
  M('3',1,'Who was Nandini Aunty?','A scientist',[('A teacher','She was a scientist'),('A doctor','She was a scientist')],'She was Vivaan\'s mother and a scientist.'),
  M('4',1,'What do Chandra and Yaan mean?','Moon and vehicle',[('Sun and star','Chandra is the Moon'),('Rocket and sky','Yaan is vehicle')],'Chandra is Moon and Yaan is vehicle.'),
  M('5',1,'Which vehicle is used to go to the Moon?','A rocket',[('A bus','Not to the Moon'),('A boat','Not to the Moon')],'A rocket carries a spacecraft.'),
  M('6',2,'When did Chandrayaan 3 land on the Moon?','23 August 2023',[('14 July 2023','That was the launch date'),('15 August 2023','Not the date')],'The text says 23 August 2023.'),
  M('7',2,'Fill in: ___ umbrella','An',[('A','Umbrella starts with a vowel sound'),('The','Not what the rule asks')],'Umbrella starts with a vowel sound.'),
  M('8',2,'Fill in: ___ dog','A',[('An','Dog starts with a consonant sound'),('Is','Not an article')],'Dog starts with a consonant sound.'),
  M('9',2,'Which is the third day of the week?','Tuesday',[('Monday','Monday is second'),('Wednesday','Wednesday is fourth')],'Sunday, Monday, Tuesday.'),
  M('10',2,'Which word starts with sw?','Swing',[('Spoon','Starts with sp'),('Stone','Starts with st')],'Swing begins with sw.'),
  F('11',2,'Chandrayaan was launched on 14 July 2023.',True,'It was launched on that date.'),
  S('12',3,'What do we call a person who studies how things work?',['scientist','a scientist'],'A scientist studies and finds out how things work.')],
 keep=['Chandrayaan','scientist'])
